import{_ as a,o as i,c as t,ae as r}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Academy Safeguarding and Minor Protection","description":"","frontmatter":{},"headers":[],"relativePath":"guide/academy-safeguarding-and-minor-protection.md","filePath":"guide/academy-safeguarding-and-minor-protection.md"}'),n={name:"guide/academy-safeguarding-and-minor-protection.md"};function o(l,e,s,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="academy-safeguarding-and-minor-protection" tabindex="-1">Academy Safeguarding and Minor Protection <a class="header-anchor" href="#academy-safeguarding-and-minor-protection" aria-label="Permalink to &quot;Academy Safeguarding and Minor Protection&quot;">​</a></h1><p>Academy is a human-first educational and cybernetics learning environment. Safety is not treated as an optional moderation layer or an afterthought. It is part of the operating model, the interaction model, and the system charter.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document defines how Academy protects minors, constrains adult interaction pathways, supports guardian oversight where appropriate, and maintains documented escalation paths for harmful or sensitive situations.</p><h2 id="core-commitments" tabindex="-1">Core commitments <a class="header-anchor" href="#core-commitments" aria-label="Permalink to &quot;Core commitments&quot;">​</a></h2><p>Academy is designed to:</p><ul><li>protect minors by default</li><li>avoid private, unreviewable adult-to-minor interaction patterns</li><li>preserve guardian visibility where appropriate</li><li>support sensitive reporting pathways</li><li>route serious issues into documented safeguarding and escalation workflows</li><li>keep the platform aligned to a human-first charter</li></ul><h2 id="interaction-principles" tabindex="-1">Interaction principles <a class="header-anchor" href="#interaction-principles" aria-label="Permalink to &quot;Interaction principles&quot;">​</a></h2><p>The core operating principles are:</p><ol><li>No private adult-to-minor direct communication outside the documented safeguarded model.</li><li>Learning interactions involving minors must be structured, attributable, and reviewable.</li><li>Guardian participation or visibility is supported where policy requires it.</li><li>Sensitive or harmful situations must have a documented reporting and escalation path.</li><li>Safety controls are part of the product architecture, not only community policy.</li></ol><h2 id="minor-protection-model" tabindex="-1">Minor protection model <a class="header-anchor" href="#minor-protection-model" aria-label="Permalink to &quot;Minor protection model&quot;">​</a></h2><p>For minor participants, Academy uses a safeguarded interaction model rather than an open-ended social platform model.</p><p>This means:</p><ul><li>interaction pathways are constrained by role and context</li><li>communication models are documented</li><li>adult access is bounded by policy</li><li>platform records and routing controls support review and escalation</li></ul><h2 id="guardian-and-family-oversight" tabindex="-1">Guardian and family oversight <a class="header-anchor" href="#guardian-and-family-oversight" aria-label="Permalink to &quot;Guardian and family oversight&quot;">​</a></h2><p>Academy supports guardian-linked participation models where appropriate. Guardian-linked workflows are intended to provide transparency, safety, and clarity without collapsing the participant’s ability to learn or report concerns.</p><p>Guardian visibility does not eliminate the need for sensitive-report pathways. A participant must still be able to raise certain concerns safely through documented safeguarding channels.</p><h2 id="reporting-and-escalation" tabindex="-1">Reporting and escalation <a class="header-anchor" href="#reporting-and-escalation" aria-label="Permalink to &quot;Reporting and escalation&quot;">​</a></h2><p>Academy maintains a documented pathway for:</p><ul><li>safety concerns</li><li>boundary violations</li><li>harmful or coercive conduct</li><li>situations requiring review, intervention, or escalation</li></ul><p>Sensitive reports may require restricted handling rather than immediate broad visibility. The platform must distinguish between ordinary review and sensitive safeguarding workflows.</p><h2 id="platform-enforcement-stance" tabindex="-1">Platform enforcement stance <a class="header-anchor" href="#platform-enforcement-stance" aria-label="Permalink to &quot;Platform enforcement stance&quot;">​</a></h2><p>Academy does not rely only on good intentions. Safety depends on:</p><ul><li>constrained interaction models</li><li>attributable actions</li><li>auditable records</li><li>clear role boundaries</li><li>escalation procedures</li><li>policy-linked system behavior</li></ul><h2 id="human-first-charter" tabindex="-1">Human-first charter <a class="header-anchor" href="#human-first-charter" aria-label="Permalink to &quot;Human-first charter&quot;">​</a></h2><p>Academy’s educational and cybernetics work is bounded by a human-first charter. Platform use that is coercive, abusive, exploitative, or anti-human is outside the intended use of the system.</p><h2 id="related-documents" tabindex="-1">Related documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related documents&quot;">​</a></h2><ul><li>Academy Interaction Contract</li><li>Guardian Rights, Sensitive Reports, and Escalation</li><li>Privacy</li><li>Terms</li></ul>',28)])])}const h=a(n,[["render",o]]);export{p as __pageData,h as default};
